import React from 'react';

const Settings = ({ onBack, settings, onUpdate }) => {
  const languages = [
    { id: 'PT-PT', label: 'Português' },
    { id: 'EN', label: 'English' }
  ];

  return (
    <div className="min-h-screen bg-raw-onyx text-raw-bone p-8 flex flex-col items-center">
      <div className="max-w-2xl w-full pt-12">
        {/* Header das Settings */}
        <div className="flex justify-between items-end mb-12 border-b border-raw-bone/10 pb-8">
          <h1 className="text-6xl font-archivo tracking-tighter uppercase">Config<span className="text-raw-cyan">.</span></h1>
          <button onClick={onBack} className="text-[10px] uppercase tracking-[0.3em] text-raw-cyan font-bold mb-2">
            [ Fechar ]
          </button>
        </div>

        <div className="space-y-16">
          {/* SECÇÃO: IDIOMA */}
          <section>
            <h2 className="text-[10px] uppercase tracking-[0.5em] text-raw-bone/30 mb-6">Region / Language</h2>
            <div className="grid grid-cols-2 gap-4">
              {languages.map((lang) => (
                <button
                  key={lang.id}
                  onClick={() => onUpdate('language', lang.id)}
                  className={`p-4 border font-archivo text-xs tracking-widest transition-all ${
                    settings.language === lang.id ? 'border-raw-cyan text-raw-cyan bg-raw-cyan/5' : 'border-raw-bone/10 text-raw-bone/40'
                  }`}
                >
                  {lang.label}
                </button>
              ))}
            </div>
          </section>

          {/* SECÇÃO: PERFORMANCE */}
          <section>
            <h2 className="text-[10px] uppercase tracking-[0.5em] text-raw-bone/30 mb-6">Interface</h2>
            <div className="flex justify-between items-center p-4 border border-raw-bone/10">
              <span className="font-archivo text-sm uppercase tracking-wider">Animações Ativas</span>
              <input 
                type="checkbox" 
                checked={settings.animations} 
                onChange={(e) => onUpdate('animations', e.target.checked)}
                className="accent-raw-cyan w-5 h-5"
              />
            </div>
          </section>

          {/* SECÇÃO: THE STORY (O TEU ABOUT AQUI) */}
          <section className="bg-white/5 p-8 border-l-2 border-raw-red">
            <h2 className="text-[10px] uppercase tracking-[0.5em] text-raw-red mb-4 font-bold">The Story</h2>
            <div className="font-inter text-sm leading-relaxed text-raw-bone/80 space-y-4">
              <p>
                A <span className="text-raw-cyan font-bold">RAW.</span> é um manifesto contra a superficialidade digital. 
                Nascida em Portugal, esta ferramenta serve para quebrar o gelo e queimar as máscaras.
              </p>
              <p className="text-[11px] italic text-raw-bone/40">
                "Desliga o automático. Encara a realidade."
              </p>
            </div>
            <div className="mt-6 pt-6 border-t border-raw-bone/5">
              <span className="text-[9px] uppercase tracking-widest text-raw-bone/20">Dev: 16ALVES02</span>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

export default Settings;
